-- Migration: Year 2 - Endocrine Pathology MCQ Bank (PART 5: 170-235)
-- Topics: Endocrine Pharmacology, Diagnostic Testing, Advanced Adrenal/Thyroid
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Endocrine Pathology', 'endocrine-pathology', 3, 2, 40)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- ENDOCRINE PHARMACOLOGY: DIABETES (1-10)
    (v_topic_id, '170. Which antidiabetic drug class is most likely to cause weight gain and edema by activating PPAR-gamma?', '["Sulfonylureas", "Thiazolidinediones (TZDs)", "GLP-1 Agonists", "SGLT2 Inhibitors"]', 1, 'TZDs (e.g., Pioglitazone) activate PPAR-gamma to increase insulin sensitivity but cause weight gain and fluid retention, and are contraindicated in heart failure.'),
    (v_topic_id, '171. A patient with Type 2 Diabetes is started on a medication that causes significant weight loss and delays gastric emptying. Drug class?', '["DPP-4 Inhibitors", "GLP-1 Agonists", "Metformin", "Meglitinides"]', 1, 'GLP-1 agonists (e.g., Liraglutide, Semaglutide) slow gastric emptying, increase satiety, and promote weight loss.'),
    (v_topic_id, '172. Which drug inhibits the intestinal brush border enzyme alpha-glucosidase?', '["Acarbose", "Pramlintide", "Sitagliptin", "Empagliflozin"]', 0, 'Acarbose and Miglitol inhibit alpha-glucosidase, delaying carbohydrate absorption and reducing postprandial glucose spikes. They commonly cause flatulence.'),
    (v_topic_id, '173. What is the mechanism of action of DPP-4 inhibitors (e.g., Sitagliptin)?', '["Decrease glucagon secretion directly", "Inhibit the breakdown of endogenous GLP-1", "Block glucose reabsorption in the kidney", "Stimulate insulin release independently of glucose"]', 1, 'DPP-4 is the enzyme that degrades incretins (GLP-1). Inhibiting it prolongs the action of endogenous GLP-1, increasing insulin release in a glucose-dependent manner.'),
    (v_topic_id, '174. Which diabetes medication works by closing ATP-sensitive K+ channels but has a shorter half-life than sulfonylureas, allowing for meal-time dosing?', '["Repaglinide", "Glimepiride", "Metformin", "Canagliflozin"]', 0, 'Meglitinides (Repaglinide) have the same mechanism as sulfonylureas but a rapid onset and short duration, ideal for postprandial spikes.'),
    (v_topic_id, '175. Which antidiabetic medication is an amylin analog that decreases glucagon release and gastric emptying?', '["Exenatide", "Pramlintide", "Saxagliptin", "Pioglitazone"]', 1, 'Pramlintide is a synthetic analog of amylin, which is co-secreted with insulin. It can be used in both Type 1 and Type 2 DM.'),
    (v_topic_id, '176. Which drug class is associated with a risk of Fournier gangrene (necrotizing fasciitis of the perineum)?', '["SGLT2 Inhibitors", "GLP-1 Agonists", "Metformin", "TZDs"]', 0, 'SGLT2 inhibitors increase urine glucose, promoting urogenital infections including candidiasis, UTIs, and rarely, Fournier gangrene.'),
    (v_topic_id, '177. A Type 2 DM patient on multiple oral meds experiences severe hypoglycemia. Which drug is most likely responsible?', '["Metformin", "Sitagliptin", "Glipizide", "Empagliflozin"]', 2, 'Sulfonylureas (like Glipizide) stimulate insulin release regardless of glucose levels, making them the most likely oral agents to cause hypoglycemia.'),
    (v_topic_id, '178. What is the classic side effect profile of Metformin?', '["Hypoglycemia and weight gain", "GI upset and lactic acidosis risk", "Pancreatitis and weight loss", "Heart failure exacerbation"]', 1, 'Metformin commonly causes diarrhea/GI upset. Lactic acidosis is rare but dangerous, especially in renal failure.'),
    (v_topic_id, '179. Regular insulin vs NPH insulin: Which has a longer duration of action?', '["Regular insulin", "NPH insulin", "They are identical", "It depends on the dose"]', 1, 'NPH is an intermediate-acting insulin. Regular insulin is short-acting.'),

    -- ENDOCRINE PHARMACOLOGY: THYROID & STEROIDS (11-20)
    (v_topic_id, '180. Which drug blocks peripheral conversion of T4 to T3 and is used in Thyroid Storm, but carries a black box warning for hepatotoxicity?', '["Methimazole", "Propylthiouracil (PTU)", "Levothyroxine", "Liothyronine"]', 1, 'PTU inhibits both TPO and 5''-deiodinase and can cause severe liver failure.'),
    (v_topic_id, '181. Why is Levothyroxine preferred over Liothyronine for hypothyroidism?', '["Levothyroxine is T3", "Liothyronine has a shorter half-life and causes more cardiac side effects", "Levothyroxine is cheaper only", "Liothyronine cannot cross the blood-brain barrier"]', 1, 'Liothyronine (T3) is rapidly absorbed and causes peaks in serum T3, leading to palpitations and toxicity. Levothyroxine (T4) provides a steady reservoir.'),
    (v_topic_id, '182. A patient on chronic high-dose prednisone is abruptly stopped. What is the expected adrenal response?', '["Addisonian crisis due to adrenal atrophy", "Hyperaldosteronism", "Cushing disease", "Conn Syndrome"]', 0, 'Exogenous steroids suppress CRH and ACTH, leading to bilateral adrenal cortical atrophy. Sudden withdrawal causes acute secondary adrenal insufficiency.'),
    (v_topic_id, '183. Which glucocorticoid effect is primarily responsible for its use in asthma?', '["Stimulation of gluconeogenesis", "Inhibition of Phospholipase A2 and NF-kB", "Upregulation of alpha-1 receptors", "Suppression of osteoblasts"]', 1, 'Glucocorticoids are potent anti-inflammatories because they inhibit PLA2 (blocking arachidonic acid release) and downregulate NF-kB (blocking inflammatory cytokines).'),
    (v_topic_id, '184. Fludrocortisone is primarily used for its:', '["Potent glucocorticoid activity", "Potent mineralocorticoid activity", "Androgenic effects", "Anti-inflammatory effects"]', 1, 'Fludrocortisone is a synthetic mineralocorticoid used as aldosterone replacement in primary adrenal insufficiency.'),
    (v_topic_id, '185. Cinacalcet is used in hyperparathyroidism. What is its mechanism?', '["Sensitizes the Calcium-Sensing Receptor (CaSR) in the parathyroid to calcium", "Inhibits osteoclasts directly", "Binds calcium in the gut", "Stimulates Vitamin D activation"]', 0, 'Cinacalcet is a calcimimetic that increases the sensitivity of the CaSR, causing the parathyroid gland to decrease PTH secretion even at lower calcium levels.'),
    (v_topic_id, '186. Sevelamer is given to patients with Chronic Kidney Disease to?', '["Increase calcium absorption", "Bind dietary phosphate in the GI tract", "Stimulate PTH release", "Replace Vitamin D"]', 1, 'Sevelamer is a non-absorbable phosphate binder used to treat hyperphosphatemia in CKD.'),
    (v_topic_id, '187. Which drug is an antagonist at the mineralocorticoid receptor and used to treat Conn Syndrome?', '["Ketoconazole", "Metyrapone", "Spironolactone", "Eplerenone"]', 2, 'Spironolactone (and Eplerenone) competitively bind the aldosterone receptor, preventing Na+ reabsorption and K+ secretion.'),
    (v_topic_id, '188. Metyrapone is used for diagnostic testing and treatment of Cushing syndrome. Mechanism?', '["Inhibits 11-beta-hydroxylase", "Blocks the ACTH receptor", "Inhibits 21-hydroxylase", "Inhibits cholesterol desmolase"]', 0, 'Metyrapone blocks cortisol synthesis at the final step (11-beta-hydroxylase), increasing 11-deoxycortisol and stimulating ACTH (in a normal pituitary).'),
    (v_topic_id, '189. Ketoconazole is an antifungal but is also used in endocrinology to?', '["Treat hyperthyroidism", "Inhibit steroid hormone synthesis in Cushing syndrome", "Replace aldosterone", "Stimulate prolactin release"]', 1, 'High-dose Ketoconazole inhibits cholesterol desmolase (and other CYP450 enzymes), effectively shutting down all steroidogenesis.'),

    -- DIAGNOSTIC TESTING (21-30)
    (v_topic_id, '190. In a high-dose dexamethasone suppression test, cortisol is successfully suppressed. This confirms?', '["Adrenal adenoma", "Ectopic ACTH secretion", "Pituitary adenoma (Cushing Disease)", "Exogenous steroid use"]', 2, 'Pituitary adenomas retain some sensitivity to negative feedback at high doses, whereas ectopic tumors and adrenal tumors do not suppress.'),
    (v_topic_id, '191. A patient with suspected Acromegaly has a normal IGF-1 level. What is the next best step?', '["Measure random GH", "Perform an Oral Glucose Tolerance Test (OGTT)", "The diagnosis is ruled out", "Order a pituitary MRI immediately"]', 2, 'IGF-1 has a long half-life and is the best initial screening test for acromegaly. If normal, the disease is highly unlikely/ruled out.'),
    (v_topic_id, '192. During an OGTT in a healthy individual, Growth Hormone levels should?', '["Increase significantly", "Remain unchanged", "Suppress to very low levels", "Fluctuate"]', 2, 'Glucose administration normally suppresses GH release. Failure to suppress confirms Acromegaly.'),
    (v_topic_id, '193. A water deprivation test is performed. Urine osmolality remains at 150 mOsm/kg. After giving Desmopressin, urine osmolality rises to 600 mOsm/kg. Diagnosis?', '["Primary Polydipsia", "Central Diabetes Insipidus", "Nephrogenic Diabetes Insipidus", "SIADH"]', 1, 'Failure to concentrate on water deprivation means DI. A dramatic response to exogenous ADH (Desmopressin) means the kidneys work, but the brain lacks ADH (Central DI).'),
    (v_topic_id, '194. In Nephrogenic DI, the response to Desmopressin during a water deprivation test is?', '["Dramatic increase in urine osmolality", "No significant change in urine osmolality", "Decrease in urine osmolality", "Massive diuresis"]', 1, 'The kidneys are resistant to ADH, so giving exogenous ADH has no effect.'),
    (v_topic_id, '195. A normal saline infusion test is used to confirm which condition?', '["Addison Disease", "Primary Hyperaldosteronism", "Cushing Syndrome", "Pheochromocytoma"]', 1, 'In a normal patient, saline expansion suppresses Aldosterone. In Primary Hyperaldosteronism, aldosterone remains inappropriately high after saline infusion.'),
    (v_topic_id, '196. Which test is the best initial screen for Pheochromocytoma?', '["Plasma renin activity", "Plasma free metanephrines", "24-hour urine cortisol", "Serum aldosterone"]', 1, 'Plasma free metanephrines or 24-hour urine fractionated metanephrines are highly sensitive for detecting catecholamine breakdown products.'),
    (v_topic_id, '197. To distinguish between Type 1 and Type 2 Diabetes in a challenging case, which test is most useful?', '["Fasting blood glucose", "HbA1c", "C-peptide levels", "Oral glucose tolerance test"]', 2, 'C-peptide is a marker of endogenous insulin production. It is low/absent in T1DM and normal/high in T2DM.'),
    (v_topic_id, '198. A secretin stimulation test shows a massive paradoxical INCREASE in serum gastrin. This is diagnostic of?', '["Peptic Ulcer Disease", "Zollinger-Ellison Syndrome", "Pernicious Anemia", "VIPoma"]', 1, 'Normally, secretin suppresses gastrin. Gastrinoma cells (Z-E syndrome) have altered receptors, causing secretin to stimulate gastrin release.'),
    (v_topic_id, '199. What is the expected TSH and Free T4 in Subclinical Hypothyroidism?', '["High TSH, Low Free T4", "Low TSH, Normal Free T4", "High TSH, Normal Free T4", "Low TSH, Low Free T4"]', 2, 'In subclinical disease, the pituitary compensates by raising TSH, which manages to keep Free T4 in the normal range.'),

    -- ADVANCED THYROID / PITUITARY / ADRENAL (31-50)
    (v_topic_id, '200. A patient presents with a solitary thyroid nodule. TSH is low. Next step?', '["Fine Needle Aspiration (FNA)", "Radioactive Iodine Uptake (RAIU) scan", "Total Thyroidectomy", "Reassurance"]', 1, 'A low TSH suggests a hyperfunctioning ("hot") nodule. RAIU confirms this. Hot nodules are rarely malignant, so FNA is usually deferred.'),
    (v_topic_id, '201. A patient presents with a solitary thyroid nodule. TSH is normal or high. Next step?', '["Radioactive Iodine Uptake (RAIU) scan", "Fine Needle Aspiration (FNA) guided by Ultrasound", "Levothyroxine suppression therapy", "Observation"]', 1, 'A normal/high TSH suggests a "cold" nodule, which carries a malignancy risk. Ultrasound-guided FNA is the next step to rule out cancer.'),
    (v_topic_id, '202. Which mutation is highly associated with Papillary Thyroid Carcinoma?', '["RET and BRAF", "RAS", "MEN1", "p53"]', 0, 'BRAF V600E mutations and RET/PTC translocations are classic drivers of Papillary Thyroid Carcinoma.'),
    (v_topic_id, '203. Which mutation is associated with Follicular Thyroid Carcinoma?', '["BRAF", "RET", "RAS and PAX8-PPAR-gamma", "BRCA1"]', 2, 'RAS mutations and PAX8-PPAR-gamma fusion genes are characteristic of Follicular CA.'),
    (v_topic_id, '204. "Orphan Annie eye" nuclei are a feature of Papillary Carcinoma due to?', '["Finely dispersed chromatin causing an empty appearance", "Viral inclusions", "Amyloid accumulation", "Glycogen deposition"]', 0, 'The chromatin is finely dispersed/cleared, giving the nucleus a hollow or "Orphan Annie" appearance.'),
    (v_topic_id, '205. Prolactin secretion is normally under constant tonic inhibition by?', '["TRH", "Serotonin", "Dopamine", "Somatostatin"]', 2, 'The hypothalamus constantly releases dopamine to suppress prolactin. A stalk section (loss of connection) leads to hyperprolactinemia.'),
    (v_topic_id, '206. Primary hypothyroidism can cause hyperprolactinemia. How?', '["Low T4 directly stimulates lactotrophs", "High TRH stimulates both TSH and Prolactin release", "TSH cross-reacts with Prolactin receptors", "Antibodies activate lactotrophs"]', 1, 'TRH is a potent stimulator of both TSH and Prolactin. In primary hypothyroidism, lack of T4 feedback leads to massive TRH release, causing galactorrhea.'),
    (v_topic_id, '207. Nelson Syndrome presents with hyperpigmentation and bitemporal hemianopsia after?', '["Bilateral adrenalectomy", "Thyroidectomy", "Pituitary radiation", "Oophorectomy"]', 0, 'Removal of the adrenals for Cushing disease removes cortisol negative feedback. An occult corticotroph adenoma can then rapidly grow (mass effect) and secrete massive ACTH/MSH (hyperpigmentation).'),
    (v_topic_id, '208. The Zona Reticularis of the adrenal cortex is primarily regulated by?', '["Renin", "ACTH", "Angiotensin II", "Potassium"]', 1, 'Both the fasciculata and reticularis are under ACTH control, while the glomerulosa is under Angiotensin II/K+ control.'),
    (v_topic_id, '209. Adrenoleukodystrophy is an X-linked disorder caused by defective?', '["Peroxisomal very long-chain fatty acid (VLCFA) metabolism", "Lysosomal glycogen degradation", "Mitochondrial oxidative phosphorylation", "Endoplasmic reticulum folding"]', 0, 'VLCFAs accumulate in the adrenal cortex and white matter of the brain, causing adrenal insufficiency and progressive demyelination in boys.'),
    (v_topic_id, '210. A patient presents with acute bilateral adrenal hemorrhage. They have a history of antiphospholipid syndrome. Mechanism?', '["Infection (Meningococcus)", "Adrenal vein thrombosis leading to hemorrhagic infarction", "Autoimmune destruction", "Metastatic infiltration"]', 1, 'Antiphospholipid syndrome causes hypercoagulability. Adrenal vein thrombosis causes venous outflow obstruction, leading to hemorrhagic infarction (mimicking Waterhouse-Friderichsen but non-infectious).'),
    (v_topic_id, '211. Conn Syndrome (Aldosterone-producing adenoma) is characterized by which acid-base disturbance?', '["High Anion Gap Metabolic Acidosis", "Normal Anion Gap Metabolic Acidosis", "Metabolic Alkalosis", "Respiratory Alkalosis"]', 2, 'Aldosterone secretes H+ into the lumen in the alpha-intercalated cells, leading to metabolic alkalosis.'),
    (v_topic_id, '212. What effect does Aldosterone have on Potassium?', '["Increases reabsorption in the proximal tubule", "Increases secretion in the principal cells", "Decreases secretion in the collecting duct", "No effect"]', 1, 'Aldosterone upregulates ROMK channels in the principal cells of the collecting duct, driving potassium secretion (loss in urine).'),
    (v_topic_id, '213. A patient has Cushing syndrome symptoms. Cortisol is elevated, ACTH is low. A CT scan shows a unilateral adrenal mass. What is the expected appearance of the contralateral adrenal gland?', '["Hyperplastic", "Normal", "Atrophic", "Hemorrhagic"]', 2, 'The autonomous adrenal mass secretes massive cortisol, suppressing ACTH. Low ACTH causes the normal contralateral adrenal gland to atrophy.'),
    (v_topic_id, '214. A patient has Cushing syndrome due to a Pituitary Adenoma. What is the expected appearance of the adrenal glands on CT?', '["Bilateral atrophy", "Unilateral hyperplasia", "Bilateral cortical hyperplasia", "Normal"]', 2, 'The pituitary adenoma secretes high ACTH, which continuously stimulates both adrenal glands, causing bilateral diffuse cortical hyperplasia.'),
    (v_topic_id, '215. What is the mechanism of hypercalcemia in Sarcoidosis?', '["Parathyroid infiltration", "Macrophages in granulomas express 1-alpha-hydroxylase", "Ectopic PTHrP production", "Bone destruction by granulomas"]', 1, 'The epithelioid macrophages in non-caseating granulomas convert 25-OH Vit D into the active 1,25-OH Vit D, leading to hypercalcemia.'),
    (v_topic_id, '216. Familial Hypocalciuric Hypercalcemia (FHH) is caused by a mutation in?', '["Vitamin D Receptor", "Calcium-Sensing Receptor (CaSR)", "PTH Receptors", "RANKL"]', 1, 'A defective CaSR requires higher serum calcium levels to suppress PTH, resulting in mild hypercalcemia, normal/high PTH, and very low urine calcium.'),
    (v_topic_id, '217. In Pseudohypoparathyroidism (Albright Hereditary Osteodystrophy), what is the genetic defect?', '["Deletion of the PTH gene", "Defective CaSR", "Mutation in the GNAS1 gene (Gs protein alpha subunit)", "Vitamin D receptor mutation"]', 2, 'The Gs protein is defective, leading to end-organ resistance to PTH. The kidneys cannot respond to PTH.'),
    (v_topic_id, '218. Maternal inheritance of the GNAS1 mutation causes Pseudohypoparathyroidism (resistance + phenotype). Paternal inheritance causes?', '["The exact same disease", "Pseudopseudohypoparathyroidism", "Primary Hyperparathyroidism", "Lethal in utero"]', 1, 'Due to genetic imprinting, paternal transmission results in the physical phenotype (short stature, short 4th/5th digits) but WITHOUT the endocrine resistance to PTH (normal Ca/PO4).'),
    (v_topic_id, '219. A 2-year-old child presents with bowing of the legs, rachitic rosary, and craniotabes. Diagnosis?', '["Osteomalacia", "Rickets", "Osteogenesis Imperfecta", "Achondroplasia"]', 1, 'Vitamin D deficiency in children causes defective mineralization of osteoid at the growth plates, leading to Rickets.'),

    -- MISC ENDO PATHOLOGY (51-66)
    (v_topic_id, '220. Osteomalacia is characterized by?', '["Decreased bone mass with normal mineralization", "Defective mineralization of newly formed osteoid", "Increased osteoclast activity only", "Woven bone formation"]', 1, 'In adults, Vitamin D deficiency causes osteomalacia: osteoblasts lay down normal osteoid matrix, but it fails to mineralize with calcium and phosphate, leaving the bones "soft".'),
    (v_topic_id, '221. Which MEN syndrome is associated with Marfanoid habitus and mucosal neuromas?', '["MEN 1", "MEN 2A", "MEN 2B", "MEN 4"]', 2, 'MEN 2B is characterized by Medullary Thyroid CA, Pheochromocytoma, mucosal neuromas (lips/tongue), and Marfanoid body habitus.'),
    (v_topic_id, '222. Paragangliomas are similar to pheochromocytomas but are located?', '["In the adrenal cortex", "Extra-adrenally (e.g., Organ of Zuckerkandl)", "In the pituitary", "In the pancreas"]', 1, 'They are extra-adrenal sympathetic ganglia tumors that can also secrete catecholamines.'),
    (v_topic_id, '223. What is the Organ of Zuckerkandl?', '["A cluster of chromaffin tissue located near the aortic bifurcation", "A region of the anterior pituitary", "A remnant of the thyroglossal duct", "The precursor to the parathyroid glands"]', 0, 'It is the most common site for an extra-adrenal pheochromocytoma (paraganglioma).'),
    (v_topic_id, '224. Pheochromocytomas stain positive for?', '["Cytokeratin", "Chromogranin and Synaptophysin", "Calretinin", "Vimentin"]', 1, 'Being neuroendocrine tumors, they express classic neuroendocrine markers like Chromogranin A and Synaptophysin.'),
    (v_topic_id, '225. Insulinomas are derived from which cell type?', '["Alpha cells", "Beta cells", "Delta cells", "Epsilon cells"]', 1, 'Beta cells of the Islets of Langerhans produce insulin.'),
    (v_topic_id, '226. Glucagonomas are derived from which cell type?', '["Alpha cells", "Beta cells", "Delta cells", "F cells"]', 0, 'Alpha cells produce glucagon.'),
    (v_topic_id, '227. Somatostatinomas are derived from which cell type?', '["Alpha cells", "Beta cells", "Delta cells", "Gamma cells"]', 2, 'Delta cells produce somatostatin.'),
    (v_topic_id, '228. VIPomas usually arise in the?', '["Stomach", "Small intestine", "Pancreas", "Adrenal gland"]', 2, 'Most Vasoactive Intestinal Peptide-secreting tumors (VIPomas) are pancreatic neuroendocrine tumors.'),
    (v_topic_id, '229. A patient with acromegaly has an increased risk of which malignancy?', '["Lung cancer", "Colorectal cancer", "Gastric cancer", "Melanoma"]', 1, 'Excess GH/IGF-1 stimulates organomegaly and increases the risk of colon polyps and colorectal cancer. Screening colonoscopy is required.'),
    (v_topic_id, '230. Gigantism occurs when a GH-secreting adenoma develops?', '["After epiphyseal closure", "Before epiphyseal closure", "During adulthood", "In the setting of high testosterone"]', 1, 'If the growth plates (epiphyses) have not yet fused (in children), excess GH causes linear bone growth (gigantism).'),
    (v_topic_id, '231. Dwarfism in Achondroplasia is due to a defect in?', '["Growth Hormone secretion", "IGF-1 production", "FGF Receptor 3 (FGFR3)", "Thyroid hormone"]', 2, 'Achondroplasia is an autosomal dominant mutation in FGFR3, which constitutively activates the receptor, INHIBITING chondrocyte proliferation at the growth plates.'),
    (v_topic_id, '232. Is GH therapy effective in Achondroplasia?', '["Yes, highly effective", "No, because the defect is in the cartilage receptor, not GH levels", "Only if given before age 2", "Yes, but only for limb lengthening"]', 1, 'GH is normal in achondroplasia. The cartilage fails to respond to growth signals due to the FGFR3 defect.'),
    (v_topic_id, '233. Empty Sella Syndrome is most often seen in?', '["Underweight young males", "Obese females with idiopathic intracranial hypertension", "Elderly patients with dementia", "Patients with MEN 1"]', 1, 'A defect in the diaphragma sellae allows CSF pressure to herniate arachnoid mater into the sella, compressing the pituitary. It is common in obese multiparous women.'),
    (v_topic_id, '234. Pituitary Apoplexy typically presents with sudden "thunderclap" headache, visual loss, and?', '["Hypotension (cardiovascular collapse)", "Severe hypertension", "Hypoglycemia only", "Thyroid storm"]', 0, 'Acute hemorrhage into an adenoma destroys the pituitary, leading to immediate loss of ACTH/Cortisol, causing shock/hypotension.'),
    (v_topic_id, '235. The most common functional pituitary adenoma is?', '["Somatotroph", "Corticotroph", "Prolactinoma", "Gonadotroph"]', 2, 'Prolactinomas account for the vast majority of functional pituitary tumors.');

    RAISE NOTICE 'SUCCESS: Endocrine Pathology MCQs Part 5 (170-235) registered.';
END $$;

COMMIT;
